<?php
/** Plugin Name: Instapass Owner Product Manager
 * Description: Direct product duration, price and credit-tenure controls.
 * Version: 1.0.2
 */
defined('ABSPATH')||exit;
function ip_om_duration($count,$unit){if(!is_scalar($count)||!preg_match('/^[1-9][0-9]{0,3}$/D',(string)$count)||!in_array($unit,['day','week','month','year'],true))throw new InvalidArgumentException('Enter a positive duration in days, weeks, months or years.');return (int)$count.' '.$unit.((int)$count===1?'':'s');}
function ip_om_parts($p){$v=(string)$p->get_meta('_instapass_validity');return preg_match('/^([1-9][0-9]*)\s*(day|week|month|year)s?$/iD',trim($v),$m)?[(int)$m[1],strtolower($m[2])]:[1,'month'];}
function ip_om_credit_term_label($g,$prefix){$p=wc_get_product($g['parent']);$term=$p?(string)$p->get_meta('_instapass_validity'):'1 month';$label=ip_tenor_duration_key($term)==='1:month'?'one full month':$term;return $prefix?'Valid for '.$label:ucfirst($label);}
function ip_om_rate_labels($rates){krsort($rates,SORT_NUMERIC);$a=[];$upper=null;foreach($rates as $minimum=>$pct){$a[$minimum]=$upper===null?$minimum.' or more days':($minimum===$upper?$minimum.' day':$minimum.'–'.$upper.' days');$upper=(int)$minimum-1;}return $a;}
function ip_om_label($g,$key){if(ipl_credit($g))return '$'.(int)$key.' credits';$p=wc_get_product($g['offers'][$key]['id']??0);if(!$p)return ipl_label($key);$m=ip_tenor_months($p);return $m?($m===1?'1 month':$m.' months'):(string)$p->get_meta('_instapass_validity');}
function ip_om_representative($g){$p=wc_get_product((int)$g['parent']);if($p&&$p->get_status()==='publish')return $p;foreach($g['offers'] as $o){$p=wc_get_product($o['id']);if($p&&$p->get_status()==='publish')return $p;}return false;}
function ip_om_fp(){ $a=[ipl_groups(),ip_ce_config(),instapass_control_rate()];foreach(ipl_groups() as $g)foreach($g['offers'] as $o){$p=wc_get_product($o['id']);$a[]=$p?ip_offer_read($p)['fingerprint']:'missing';}return hash('sha256',wp_json_encode($a));}
function ip_om_group_index($key,$groups){foreach($groups as $i=>$g)if($g['key']===$key)return $i;throw new InvalidArgumentException('Product tile not found.');}
function ip_om_register($id,$fp){if(!add_option('ip_om_save_lock',time(),'','no'))throw new RuntimeException('Another product save is running.');wc_transaction_query('start');try{$key=ip_om_register_unlocked($id,$fp);wc_transaction_query('commit');return $key;}catch(Throwable $e){wc_transaction_query('rollback');clean_post_cache($id);wc_delete_product_transients($id);wp_cache_delete('instapass_launch_groups','options');throw $e;}finally{delete_option('ip_om_save_lock');}}
function ip_om_register_unlocked($id,$fp){if(!current_user_can('manage_woocommerce')||!current_user_can('edit_post',$id)||!is_string($fp)||!hash_equals(ip_om_fp(),$fp))throw new RuntimeException('Permission denied or stale editor.');$p=wc_get_product($id);if(!$p||!$p->is_type('simple')||!$p->is_virtual()||ipl_offer($id))throw new InvalidArgumentException('Choose an unlisted simple digital product.');$groups=ipl_groups();$name=trim((string)$p->get_meta('_instapass_tenor_family'))?:$p->get_name();$found=null;foreach($groups as $i=>$g)if(strcasecmp($g['name'],$name)===0)$found=$i;
if($found!==null){foreach($groups[$found]['offers'] as $o){$other=wc_get_product($o['id']);if($other&&ip_tenor_duration_key($other->get_meta('_instapass_validity'))===ip_tenor_duration_key($p->get_meta('_instapass_validity')))throw new InvalidArgumentException('That duration already exists. Use Add a duration or edit the existing offer.');}$key=max(array_map('intval',array_keys($groups[$found]['offers'])))+1;$groups[$found]['offers'][$key]=['id'=>$id,'ready'=>false];$family=$groups[$found]['key'];}else{$family='product-'.$id;$groups[]=['key'=>$family,'name'=>$name,'caption'=>wp_strip_all_tags($p->get_meta('_instapass_brief')),'parent'=>$id,'enabled'=>true,'offers'=>[1=>['id'=>$id,'ready'=>false]]];}
$p->set_status('draft');$p->update_meta_data('_instapass_tenor_family',$name);$p->update_meta_data('_instapass_tenor_group',hash('sha256',strtolower($name)));$p->update_meta_data('_ip_launch_family',$family);$p->save();update_option('instapass_launch_groups',$groups,false);return $family;}
function ip_om_existing_form($fp){$choices=[];foreach(wc_get_products(['limit'=>-1,'status'=>['publish','draft','private'],'orderby'=>'name','order'=>'ASC']) as $p)if($p->is_type('simple')&&$p->is_virtual()&&!ipl_offer($p->get_id())&&current_user_can('edit_post',$p->get_id()))$choices[]=$p;if(!$choices)return;echo '<section class="ipom-card"><h2>Bring an existing product into the storefront</h2><p>Prepare an unlisted product as a draft tile, then review its duration and prices here before activating it.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ip_om_save"><input type="hidden" name="mode" value="existing"><input type="hidden" name="fingerprint" value="'.esc_attr($fp).'">';wp_nonce_field('ip_om_save');echo '<select name="existing_id">';foreach($choices as $p)echo '<option value="'.$p->get_id().'">'.esc_html($p->get_name()).'</option>';echo '</select> ';submit_button('Prepare existing product','secondary','submit',false);echo '</form></section>';}
function ip_om_description_for_term($description,$g,$duration){$term='<p class="ipom-access-term">'.esc_html($g['name'].' — '.$duration.' of access.').' The full term is paid upfront. We absorb applicable taxes; no extra tax at checkout.</p>';if(str_contains($description,'class="ipom-access-term"'))return preg_replace_callback('/<p class="ipom-access-term">.*?<\/p>/s',fn()=>$term,$description);$owned=['<p>ChatGPT credits provide one full month and cost40% of the selected credit balance before any qualifying bundle coupon.</p>','<p>Cursor Pro annual access. The full year is paid upfront, with no automatic monthly charge. We absorb applicable taxes; no extra tax at checkout.</p>','<p>Annual access is paid upfront. We absorb applicable taxes; no extra tax at checkout.</p>'];foreach($owned as $paragraph)if(str_contains($description,$paragraph))return str_replace($paragraph,$term,$description);return $term.$description;}
function ip_om_plan_values($g,$p,$in){
 $v=ip_offer_read($p?:null);$duration=ip_om_duration($in['duration_count']??'',(string)($in['duration_unit']??''));$v['duration']=$duration;
 foreach(['usd','gbp','eur','pkr'] as $c)foreach(['regular','sale'] as $t){$k=$c.'_'.$t;if(!isset($in[$k])||!is_string($in[$k]))throw new InvalidArgumentException('Price fields are incomplete. Reload the editor.');$v[$k]=trim($in[$k]);$v[$c.'_discount']='';}
 $v['pkr_mode']=(string)($in['pkr_mode']??'');$v['status']=!empty($in['active'])?'publish':'draft';$v['family']=$g['name'];$v['name']=$p&&$p->get_id()===(int)$g['parent']?$g['name']:$g['name'].' — '.$duration;
 if(($in['price_basis']??'total')==='monthly'){
  [$n,$unit]=ip_om_parts_from_text($duration);if(!in_array($unit,['month','year'],true))throw new InvalidArgumentException('Monthly-rate entry needs a month or year duration. Use full-term totals for days/weeks.');$months=$n*($unit==='year'?12:1);
  foreach(['usd','gbp','eur','pkr'] as $c)foreach(['regular','sale'] as $t){$k=$c.'_'.$t;if($v[$k]===''||($c==='pkr'&&$v['pkr_mode']==='auto'))continue;if(!preg_match('/^(?:0|[1-9][0-9]*)(?:\.[0-9]{1,2})?$/D',$v[$k]))throw new InvalidArgumentException('Enter money with at most two decimals.');$v[$k]=number_format((int)round((float)$v[$k]*100)*$months/100,2,'.','');}
 }elseif(($in['price_basis']??'total')!=='total')throw new InvalidArgumentException('Choose a valid price-entry basis.');
 if(!$p){$source=wc_get_product($g['parent']);if($source){$v=ip_om_inherit($v,$source);}$v['id']='0';$v['fingerprint']='new';$v['sku']='';$v['visibility']='hidden';$v['name']=$g['name'].' — '.$duration;$v['manage_stock']='no';$v['stock_quantity']='';$v['stock']='instock';$v['sale_from']='';$v['sale_to']='';}
 if(!empty($in['active'])&&$v['usd_regular']==='')throw new InvalidArgumentException('Enter a positive full-term USD price before activation.');if(!$p||ip_tenor_duration_key($p->get_meta('_instapass_validity'))!==ip_tenor_duration_key($duration))$v['description']=ip_om_description_for_term($v['description'],$g,$duration);return ip_offer_values($v);
}
function ip_om_parts_from_text($s){preg_match('/^([1-9][0-9]*) (day|week|month|year)s?$/D',$s,$m);return [(int)$m[1],$m[2]];}
function ip_om_inherit($v,$p){$source=ip_offer_read($p);foreach(['brand','brand_secondary','image_id','access_type','activation','renewable','categories','card_brief','description','brief','plan'] as $k)$v[$k]=$source[$k];return $v;}
function ip_om_save($key,$id,$in,$fingerprint){
 if(!current_user_can('manage_woocommerce')||!current_user_can('edit_products'))throw new RuntimeException('Permission denied.');if(!is_string($fingerprint)||!hash_equals(ip_om_fp(),$fingerprint))throw new RuntimeException('Products or prices changed. Reload before saving.');$groups=ipl_groups();$i=ip_om_group_index($key,$groups);$g=$groups[$i];if(ipl_credit($g))throw new InvalidArgumentException('Use the credit controls for this product.');$p=$id?wc_get_product($id):null;$found=!$id;foreach($g['offers'] as $o)if((int)$o['id']===$id)$found=true;if(!$found||($id&&!$p))throw new InvalidArgumentException('Offer is not part of this tile.');$v=ip_om_plan_values($g,$p,$in);
 foreach($g['offers'] as $o){if((int)$o['id']===$id)continue;$other=wc_get_product($o['id']);if($other&&ip_tenor_duration_key($other->get_meta('_instapass_validity'))===ip_tenor_duration_key($v['duration']))throw new InvalidArgumentException('That duration already exists. Edit its price instead.');}
 if(!add_option('ip_om_save_lock',time(),'','no'))throw new RuntimeException('Another product save is running. Try again.');wc_transaction_query('start');$saved=0;
 try{$saved=ip_offer_save($v);if($id){foreach($groups[$i]['offers'] as &$o)if((int)$o['id']===$id)$o['ready']=$v['status']==='publish';unset($o);}else{$next=max(array_map('intval',array_keys($g['offers'])))+1;$groups[$i]['offers'][$next]=['id'=>$saved,'ready'=>$v['status']==='publish'];}$fresh=wc_get_product($saved);$fresh->update_meta_data('_ip_launch_family',$key);$fresh->save();if(!update_option('instapass_launch_groups',$groups,false)&&get_option('instapass_launch_groups')!==$groups)throw new RuntimeException('Could not save the tile mapping.');wc_transaction_query('commit');return $saved;}catch(Throwable $e){wc_transaction_query('rollback');if($saved){clean_post_cache($saved);wc_delete_product_transients($saved);}wp_cache_delete('instapass_launch_groups','options');throw $e;}finally{delete_option('ip_om_save_lock');}
}
function ip_om_credit_save($key,$in,$fp){
 if(!current_user_can('manage_woocommerce')||!current_user_can('edit_products')||!is_string($fp)||!hash_equals(ip_om_fp(),$fp))throw new RuntimeException('Permission denied or stale editor. Reload first.');$groups=ipl_groups();$g=$groups[ip_om_group_index($key,$groups)];if($key!=='chatgpt-credits')throw new InvalidArgumentException('Claude uses the dedicated expiry controls.');$duration=ip_om_duration($in['duration_count']??'',(string)($in['duration_unit']??''));$rate=$in['base_percent']??'';if(!is_string($rate)||!preg_match('/^(?:0|[1-9][0-9]?|100)(?:\.[0-9]{1,2})?$/D',$rate)||(float)$rate<=0||(float)$rate>100)throw new InvalidArgumentException('Enter a base percentage above0and at most100.');$planned=[];
 foreach($g['offers'] as $face=>$o){$p=wc_get_product($o['id']);$v=ip_offer_read($p);$price=number_format(round($face*(float)$rate)/100,2,'.','');foreach(['usd','gbp','eur'] as $c){$v[$c.'_regular']=$price;$v[$c.'_sale']='';$v[$c.'_discount']='';}$v['pkr_mode']='auto';$v['duration']=$duration;$v['description']=ip_om_description_for_term($v['description'],$g,$duration);$v['brief']='<p>'.esc_html('Choose your credit balance. Valid for '.$duration.'.').'</p>';$v['sale_from']='';$v['sale_to']='';$planned[]=ip_offer_values($v);}
 if(!add_option('ip_om_save_lock',time(),'','no'))throw new RuntimeException('Another save is running.');wc_transaction_query('start');try{foreach($planned as $v)ip_offer_save($v);$groups[ip_om_group_index($key,$groups)]['caption']='Choose your credit balance. Valid for '.$duration.'.';update_option('instapass_launch_groups',$groups,false);wc_transaction_query('commit');}catch(Throwable $e){wc_transaction_query('rollback');foreach($g['offers'] as $o){clean_post_cache($o['id']);wc_delete_product_transients($o['id']);}wp_cache_delete('instapass_launch_groups','options');throw $e;}finally{delete_option('ip_om_save_lock');}
}
function ip_om_fields($p=null){$v=ip_offer_read($p);[$n,$u]=$p?ip_om_parts($p):[1,'month'];echo '<div class="ipom-fields"><label>Duration <input name="duration_count" type="number" min="1" max="9999" value="'.absint($n).'" required style="width:75px"> <select name="duration_unit">';foreach(['day','week','month','year'] as $unit)echo '<option value="'.$unit.'" '.selected($u,$unit,false).'>'.esc_html(ucfirst($unit).'s').'</option>';echo '</select></label><label>Prices entered as <select name="price_basis"><option value="total">Full-term totals</option><option value="monthly">Monthly rates (month/year terms only)</option></select></label><label><input type="checkbox" name="active" value="1" '.checked($p&&$p->get_status()==='publish'&&!empty(ipl_offer($p->get_id())['ready']),true,false).'> Active and ready to buy</label></div><div class="ipom-prices">';
 foreach(['usd'=>'USD','gbp'=>'GBP','eur'=>'EUR','pkr'=>'PKR'] as $c=>$label){echo '<fieldset><legend>'.esc_html($label).'</legend>';if($c==='pkr')echo '<select name="pkr_mode"><option value="auto" '.selected($v['pkr_mode'],'auto',false).'>Automatic from USD</option><option value="fixed" '.selected($v['pkr_mode'],'fixed',false).'>Fixed PKR</option></select>';foreach(['regular'=>'Base price','sale'=>'Sale price (optional)'] as $t=>$l)echo '<label>'.esc_html($l).'<input name="'.$c.'_'.$t.'" type="text" inputmode="decimal" value="'.esc_attr($v[$c.'_'.$t]).'" style="width:100%"></label>';echo '</fieldset>';}echo '</div><p class="description">Full-term totals are charged upfront. Choose Monthly rates before entering new monthly amounts; the server multiplies them by the selected months. Blank GBP/EUR keeps that currency unavailable. Automatic PKR ignores fixed price fields. Existing sale dates are preserved; advanced settings are in the full offer editor.</p>';
}
function ip_om_form_start($key,$id,$fp,$mode='plan'){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ip_om_save"><input type="hidden" name="mode" value="'.esc_attr($mode).'"><input type="hidden" name="group" value="'.esc_attr($key).'"><input type="hidden" name="id" value="'.absint($id).'"><input type="hidden" name="fingerprint" value="'.esc_attr($fp).'">';wp_nonce_field('ip_om_save');}
add_action('admin_menu',function(){add_submenu_page('instapass-control','Product Manager','Product Manager','manage_woocommerce','instapass-product-manager','ip_om_admin');},35);
function ip_om_admin(){if(!current_user_can('manage_woocommerce'))return;$fp=ip_om_fp();echo '<div class="wrap"><h1>Product Manager</h1><p>Edit a duration and its prices, then Save. Add a duration below its product to put a new choice on the same storefront tile. Deactivating an offer preserves its orders.</p>';if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Product settings saved.</p></div>';echo '<p><a class="button" href="'.esc_url(admin_url('admin.php?page=instapass-offers')).'">Add a new product / advanced editor</a> <a class="button" href="'.esc_url(admin_url('admin.php?page=instapass-product-tiles')).'">Tile names and visibility</a></p><style>.ipom-card{background:#fff;border:1px solid #ccd0d4;padding:20px;margin:18px 0;max-width:1100px}.ipom-card>summary{cursor:pointer;font-size:18px}.ipom-card[open]>summary{margin-bottom:16px}.ipom-fields{display:flex;gap:16px;flex-wrap:wrap;align-items:center}.ipom-prices{display:grid;grid-template-columns:repeat(4,minmax(120px,1fr));gap:16px;margin:15px 0}.ipom-prices label{display:block;margin:8px 0}.ipom-offer{border-top:1px solid #ddd;margin-top:18px;padding-top:15px}@media(max-width:800px){.ipom-prices{grid-template-columns:repeat(2,minmax(100px,1fr))}}</style>';
 foreach(ipl_groups() as $g){echo '<details class="ipom-card" id="'.esc_attr($g['key']).'"'.(($_GET['group']??'')===$g['key']?' open':'').'><summary><strong>'.esc_html($g['name']).'</strong> — manage durations and prices</summary>';if(ipl_credit($g)){if($g['key']==='claude-credits')echo '<p>Choose calendar-month or fixed-day batch tenure, remaining-day bands and rates in the dedicated control.</p><a class="button button-primary" href="'.esc_url(admin_url('admin.php?page=instapass-credit-cycle')).'">Edit Claude credit tenure and rates</a>';else{$p=wc_get_product($g['parent']);[$n,$u]=ip_om_parts($p);$face=(int)$p->get_meta('_instapass_credit_amount');$rate=$face?(float)$p->get_regular_price('edit')/$face*100:40;ip_om_form_start($g['key'],0,$fp,'credit');echo '<p>These settings apply to every ChatGPT credit balance. Independent GBP/EUR use the same numeric prices; PKR becomes automatic.</p><label>Access duration <input name="duration_count" type="number" min="1" max="9999" value="'.absint($n).'"> <select name="duration_unit">';foreach(['day','week','month','year'] as $unit)echo '<option value="'.$unit.'" '.selected($u,$unit,false).'>'.ucfirst($unit).'s</option>';echo '</select></label> <label>Price as % of credit face value <input name="base_percent" type="number" min="0.01" max="100" step="0.01" value="'.esc_attr($rate).'" required></label>';submit_button('Save credit tenure and prices','primary','submit',false);echo '</form>';}echo '</details>';continue;}
 foreach($g['offers'] as $o){$p=wc_get_product($o['id']);if(!$p)continue;echo '<div class="ipom-offer"><h3>'.esc_html($p->get_meta('_instapass_validity')).' <small>— '.esc_html($p->get_status()==='publish'?'Active':'Deactivated').'</small></h3>';ip_om_form_start($g['key'],$p->get_id(),$fp);ip_om_fields($p);submit_button('Save this duration','primary','submit',false);echo ' <a href="'.esc_url(admin_url('admin.php?page=instapass-offers&offer='.$p->get_id())).'">Stock, discounts, logo and advanced settings</a></form></div>';}
 echo '<details class="ipom-offer"><summary><strong>Add a duration to '.esc_html($g['name']).'</strong></summary>';ip_om_form_start($g['key'],0,$fp);ip_om_fields();submit_button('Create duration','primary','submit',false);echo '</form></details></details>';}ip_om_existing_form($fp);echo '</div>';
}
add_action('admin_post_ip_om_save',function(){if(!current_user_can('manage_woocommerce'))wp_die('Permission denied','',['response'=>403]);check_admin_referer('ip_om_save');$in=wp_unslash($_POST);try{$key=is_string($in['group']??null)?$in['group']:'';$fp=$in['fingerprint']??null;if(($in['mode']??'')==='existing')$key=ip_om_register(absint($in['existing_id']??0),$fp);elseif(($in['mode']??'')==='credit')ip_om_credit_save($key,$in,$fp);else ip_om_save($key,absint($in['id']??0),$in,$fp);}catch(Throwable $e){wp_die(esc_html($e->getMessage()),'Could not save product',['response'=>400]);}wp_safe_redirect(admin_url('admin.php?page=instapass-product-manager&saved=1&group='.rawurlencode($key).'#'.rawurlencode($key)));exit;});
add_action('admin_footer',function(){if(($_GET['page']??'')!=='instapass-product-manager'||!current_user_can('manage_woocommerce'))return;echo '<script>(function(){const rate='.wp_json_encode(instapass_control_rate()).';function preview(f){if(!f.querySelector("[name=usd_regular]"))return;let out=f.querySelector(".ipom-preview");if(!out){out=document.createElement("p");out.className="ipom-preview";out.setAttribute("role","status");f.querySelector(".ipom-prices").after(out);}const n=Number(f.elements.duration_count.value),unit=f.elements.duration_unit.value,months=unit==="year"?n*12:unit==="month"?n:0,basis=f.elements.price_basis.value,mul=basis==="monthly"?months:1;const bits=[];for(const c of ["usd","gbp","eur","pkr"]){let raw=f.elements[c+"_regular"].value;if(c==="pkr"&&f.elements.pkr_mode.value==="auto"){const usd=Number(f.elements.usd_regular.value)*mul;if(Number.isFinite(usd)&&usd>0)bits.push("PKR "+(Math.round(usd*Number(rate)/100)*100).toFixed(0)+" upfront (automatic)");continue;}if(raw==="")continue;const total=Number(raw)*mul;if(Number.isFinite(total)&&total>=0)bits.push(c.toUpperCase()+" "+total.toFixed(2)+" upfront"+(months?"; "+(total/months).toFixed(2)+"/month equivalent":""));}out.textContent="Preview: "+bits.join(" | ");}document.querySelectorAll("form").forEach(preview);document.addEventListener("input",e=>{const f=e.target.closest("form");if(f)preview(f);});document.addEventListener("change",e=>{const f=e.target.closest("form");if(f)preview(f);});})();</script>';});
// Changing a sold duration requires reviewing the current checkout quote even if the amount stayed the same.
add_filter('woocommerce_cart_hash',function($hash){if(!function_exists('WC')||!WC()->cart)return $hash;$terms=[];foreach(WC()->cart->get_cart() as $i){$p=wc_get_product($i['data']->get_id());if($p&&ipl_offer($p->get_id()))$terms[$p->get_id()]=[$p->get_name('edit'),$p->get_meta('_instapass_validity'),$p->get_meta('_instapass_plan')];}return $terms?hash('sha256',$hash.'|offer-terms|'.wp_json_encode($terms)):$hash;},2600);
function ip_om_cycle_state($at=null,$config=null){$c=$config??ip_ce_config();$at=$at??ip_ce_now();$month=(new DateTimeImmutable('@'.$at))->setTimezone(wp_timezone())->modify('first day of this month')->setTime(0,0,0);$start=ip_ce_boundary($month,(int)$c['start_day']);if($start->getTimestamp()>$at)$month=$month->modify('-1 month');$start=ip_ce_boundary($month,(int)$c['start_day']);$end=($c['tenure_mode']??'calendar')==='days'?$start->modify('+'.(int)($c['tenure_days']??28).' days'):ip_ce_boundary($month->modify('+1 month'),(int)$c['start_day']);$days=max(0,(int)ceil(($end->getTimestamp()-$at)/DAY_IN_SECONDS));$rates=$c['rates'];krsort($rates,SORT_NUMERIC);$rate='0.00';foreach($rates as $minimum=>$pct)if($days>=(int)$minimum){$rate=$pct;break;}return ['enabled'=>!empty($c['enabled']),'start'=>$start->getTimestamp(),'expiry'=>$end->getTimestamp(),'days'=>$days,'percent'=>$rate,'config_hash'=>hash('sha256',wp_json_encode($c))];}
function ip_om_cycle_validate($in){$v=ip_ce_validate_legacy($in+['rates'=>ip_ce_defaults()['rates']]);$mode=$in['tenure_mode']??'calendar';$days=$in['tenure_days']??'28';if(!in_array($mode,['calendar','days'],true)||!is_string($days)||!preg_match('/^(?:[1-9]|[12][0-9]|3[01])$/D',$days))throw new InvalidArgumentException('Choose calendar-month tenure or1–31 fixed days.');$v['tenure_mode']=$mode;$v['tenure_days']=(int)$days;
 if(isset($in['tiers'])){if(!is_array($in['tiers'])||count($in['tiers'])!==5)throw new InvalidArgumentException('Enter five day bands.');$rates=[];foreach($in['tiers'] as $row){$min=$row['minimum']??'';$pct=$row['percent']??'';if(!is_string($min)||!preg_match('/^(?:[1-9]|[12][0-9]|3[01])$/D',$min)||isset($rates[(int)$min])||!is_string($pct)||!preg_match('/^(?:0|[1-9][0-9]?|100)(?:\.[0-9]{1,2})?$/D',$pct)||(float)$pct<=0||(float)$pct>100)throw new InvalidArgumentException('Use unique positive day thresholds and rates above0and at most100.');$rates[(int)$min]=number_format((float)$pct,2,'.','');}krsort($rates,SORT_NUMERIC);if(!isset($rates[1]))throw new InvalidArgumentException('The lowest day threshold must be1.');$last=101;foreach($rates as $pct){if((float)$pct>$last)throw new InvalidArgumentException('Rates must stay the same or fall as expiry approaches.');$last=(float)$pct;}$v['rates']=$rates;}return $v;
}
function ip_om_cycle_admin(){if(!current_user_can('manage_woocommerce'))return;$c=ip_ce_config();$s=ip_ce_state();echo '<div class="wrap"><h1>Claude Credit Tenure & Pricing</h1><p>Choose how long each monthly batch stays valid and edit the day bands/rates. ChatGPT settings are separate in <a href="'.esc_url(admin_url('admin.php?page=instapass-product-manager')).'">Product Manager</a>.</p><p>Current batch: '.esc_html(wp_date('j M Y H:i',$s['start']).' → '.wp_date('j M Y H:i',$s['expiry']).' '.wp_timezone_string()).'. About '.absint($s['days']).' days remaining; rate '.esc_html((float)$s['percent']).'%.</p><form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="ip_ce_save"><input type="hidden" name="fingerprint" value="'.esc_attr(ip_ce_fingerprint()).'">';wp_nonce_field('ip_ce_save');echo '<table class="form-table"><tr><th>Sales</th><td><label><input type="checkbox" name="enabled" value="1" '.checked($c['enabled'],true,false).'> Enable Claude credit purchases</label></td></tr><tr><th>Monthly start day</th><td><input name="start_day" type="number" min="1" max="31" value="'.absint($c['start_day']).'" required></td></tr><tr><th>Batch tenure</th><td><select name="tenure_mode"><option value="calendar" '.selected($c['tenure_mode'],'calendar',false).'>One calendar month</option><option value="days" '.selected($c['tenure_mode'],'days',false).'>Fixed number of days</option></select> <input name="tenure_days" type="number" min="1" max="31" value="'.absint($c['tenure_days']).'" required> days when fixed mode is selected<p class="description">A new batch begins on the monthly start day. A fixed-day batch that expires before the next monthly start is unavailable until renewal.</p></td></tr>';$i=0;$rates=$c['rates'];krsort($rates,SORT_NUMERIC);foreach($rates as $min=>$pct){echo '<tr><th>Remaining-time band '.($i+1).'</th><td>At least <input name="tiers['.$i.'][minimum]" type="number" min="1" max="31" value="'.absint($min).'" required> days remaining: <input name="tiers['.$i.'][percent]" type="number" min="0.01" max="100" step="0.01" value="'.esc_attr($pct).'" required> % of credit face value</td></tr>';$i++;}echo '</table><p>Lowest threshold must be1day; rates may stay level or decrease toward expiry. Short-month start days clamp to the last day. Prices use the stored40% top-tier base; existing orders keep their purchased expiry. TOOLKIT5 can apply afterward.</p>';submit_button('Save tenure and rates');echo '</form></div>';}
// The existing full editor remains the place to choose logos and create a new product.
// A genuinely new managed family is now registered as a storefront tile automatically.
add_action('woocommerce_new_product',function($id,$product=null){$p=$product?:wc_get_product($id);if(!$p||$p->get_meta('_ip_offer_managed')!=='yes'||!$p->is_virtual())return;$name=trim((string)$p->get_meta('_instapass_tenor_family'));if($name==='')$name=$p->get_name();$groups=ipl_groups();foreach($groups as $g)if(strcasecmp($g['name'],$name)===0)return;if($p->get_meta('_instapass_tenor_group')===''){$p->update_meta_data('_instapass_tenor_family',$name);$p->update_meta_data('_instapass_tenor_group',hash('sha256',strtolower($name)));$p->save_meta_data();}$groups[]=['key'=>'product-'.$id,'name'=>$name,'caption'=>wp_strip_all_tags($p->get_meta('_instapass_brief')),'parent'=>(int)$id,'enabled'=>true,'offers'=>[1=>['id'=>(int)$id,'ready'=>$p->get_status()==='publish'&&(float)$p->get_regular_price('edit')>0]]];update_option('instapass_launch_groups',$groups,false);},40,2);
